def main():
    with open(HOSTELS_PATH, "r", encoding="utf-8") as f:
        hostels = json.load(f)

    by_id = {h["id"]: h for h in hostels}

    field_counts = {
        "bed_bug_reports": {"true": 0, "false": 0, "null": 0},
        "lockers_available": {"true": 0, "false": 0, "null": 0},
        "hair_dryer_available": {"true": 0, "false": 0, "null": 0},
        "clothes_drying_facility": {"true": 0, "false": 0, "null": 0},
        "curfew_policy": {"populated": 0, "null": 0},
    }
    nearby_added = 0

    for r in RESULTS:
        h = by_id.get(r["id"])
        if h is None:
            print(f"WARNING: id {r['id']} not found in hostels.json")
            continue

        services = h.setdefault("services", {})
        services["bed_bug_reports"] = r["bed_bug_reports"]
        services["lockers"] = r["lockers"]
        services["hair_dryer_available"] = r["hair_dryer_available"]
        services["clothes_drying_facility"] = r["clothes_drying_facility"]
        services["curfew_policy"] = r["curfew_policy"]

        research_sources = h.setdefault("research_sources", {})
        research_sources["pilot_2026_08_thailand_india"] = r["sources"]

        if "nearby" in r:
            h.setdefault("location", {})["nearby"] = r["nearby"]
            nearby_added += 1

        # tally reliability stats
        for field, key in [("bed_bug_reports", "bed_bug_reports")]:
            v = r[field]
            field_counts[key]["true" if v is True else "false" if v is False else "null"] += 1
        field_counts["lockers_available"]["true" if r["lockers"]["available"] is True else "false" if r["lockers"]["available"] is False else "null"] += 1
        field_counts["hair_dryer_available"]["true" if r["hair_dryer_available"] is True else "false" if r["hair_dryer_available"] is False else "null"] += 1
        field_counts["clothes_drying_facility"]["true" if r["clothes_drying_facility"] is True else "false" if r["clothes_drying_facility"] is False else "null"] += 1
        field_counts["curfew_policy"]["populated" if r["curfew_policy"] else "null"] += 1

    with open(HOSTELS_PATH, "w", encoding="utf-8") as f:
        json.dump(hostels, f, indent=2, ensure_ascii=False)

    print(f"Merged {len(RESULTS)} hostel research results.")
    print(f"New location.nearby added for {nearby_added} previously-gap hostels.\n")
    print("Field reliability (out of 68):")
    for field, counts in field_counts.items():
        print(f"  {field}: {counts}")


if __name__ == "__main__":
    main()
